// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.robustnessimport timber.log.Timberimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.core.ModelManagerimport com.roshan.persona.vision.core.OmniSlmRuntimeimport com.roshan.persona.vision.ocr.RgbImageimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.asyncimport kotlinx.coroutines.coroutineScopeimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.withContextimport kotlinx.coroutines.yield/** * NOUS — First-Frame Parallel Loader (Module 6 v4.2 — HIGH Priority Patch). * * Implements the **parallel camera + model loading** pipeline with v2 stack * fallback, per v4.2 §"First-Frame Parallel Pipeline" + reviewer's advice: * * > "prioritize VisionFailureHandler and First-frame parallel loading above * > all else. If the camera doesn't start reliably or the first result isn't * > fast, the quality of the Omni-SLM model will be irrelevant because the * > user will have already closed the app." * * ## How it works (per v4.2 sequence diagram) * * ``` * User opens NOUS camera → *   ↓ (parallel) *   ├── Camera2 API opens (100ms warm / 500ms cold) *   │ *   └── Omni-SLM loads via mmap (5ms) + pre-fault (600ms cold) *       ↓ *       If Omni-SLM ready → use Omni-SLM for first frame *       If Omni-SLM NOT ready → use v2 stack (MiniLM + BERT-tiny) for first frame *       ↓ *   Camera captures first frame (200ms AE + AF) *   ↓ *   Process frame with whatever model is ready *   ↓ *   Display result + TTS (100ms) *   ↓ *   [If v2 stack was used] Omni-SLM becomes ready → upgrade subsequent frames * ``` * * ## Performance (per v4.2) * * | Scenario | First-Result Latency | Notes | * |----------|---------------------|-------| * | Warm start (Omni-SLM in page cache) | 1.3 seconds | Camera 100ms + frame 200ms + inference 200ms + display 100ms | * | Cold start (v2 stack fallback) | 1.1 seconds | Camera 500ms + frame 200ms + v2 inference 300ms + display 100ms | * | Cold start (Omni-SLM upgraded) | 2.3 seconds | v2 result at 1.1s + Omni-SLM upgrade at +1.2s | * * ## User Perception * * - Warm: "instant" (1.3s) * - Cold: "fast initial answer" (1.1s via v2) + "seamless upgrade" (Omni-SLM at 2.3s) * - User never sees a blank screen or loading spinner (v2 result appears immediately) * * @see <a href="docs/strategy/module-6-vision-strategy-v4.2-final.md">§First-Frame Parallel Pipeline</a> */class FirstFrameParallelLoader(    private val modelManager: ModelManager,    private val v2StackProvider: V2StackProvider,    private val cameraProvider: CameraProvider,    private val failureHandler: VisionFailureHandler,    private val dispatcher: CoroutineDispatcher,) {    private val _loadingState = MutableStateFlow(FirstFrameLoadingState.IDLE)    val loadingState: StateFlow<FirstFrameLoadingState> = _loadingState.asStateFlow()    /** True if Omni-SLM was used for the first frame (vs v2 fallback). */    @Volatile    private var usedOmniSlmForFirstFrame: Boolean = false    /** Total cold starts (for stats). */    @Volatile    private var totalColdStarts: Int = 0    /** Total warm starts (for stats). */    @Volatile    private var totalWarmStarts: Int = 0    /** Total v2 fallbacks (for stats). */    @Volatile    private var totalV2Fallbacks: Int = 0    /**     * Initialize the vision pipeline in parallel — camera + model loading.     *     * @return the [FirstFrameResult] — contains the camera + Omni-SLM runtime     *         (or v2 stack if Omni-SLM not ready) + which stack was used.     */    suspend fun initializeParallel(): FirstFrameResult = withContext(dispatcher) {        _loadingState.value = FirstFrameLoadingState.INITIALIZING        Timber.tag(TAG).i("First-frame parallel initialization started.")        coroutineScope {            // Launch camera + model loading in parallel.            val cameraDeferred = async {                try {                    val cameraStart = System.currentTimeMillis()                    cameraProvider.openCamera()                    val cameraMs = System.currentTimeMillis() - cameraStart                    Timber.tag(TAG).d("Camera opened in ${cameraMs}ms.")                    cameraMs                } catch (t: Throwable) {                    Timber.tag(TAG).e("Camera open failed", t)                    failureHandler.handleFailure(                        VisionFailureType.CAMERA_PERMISSION_DENIED,                        VisionFailureContext(engineName = "Camera2", errorMessage = t.message),                    )                    -1L  // Signal failure                }            }            val modelDeferred = async {                try {                    val modelStart = System.currentTimeMillis()                    val runtime = modelManager.getOmniSlmRuntime()                    val modelMs = System.currentTimeMillis() - modelStart                    Timber.tag(TAG).d("Omni-SLM loaded in ${modelMs}ms (disabled=${runtime.isDisabled}).")                    Pair(runtime, modelMs)                } catch (t: Throwable) {                    Timber.tag(TAG).e("Omni-SLM load failed", t)                    failureHandler.handleFailure(                        VisionFailureType.MODEL_LOAD_FAILURE,                        VisionFailureContext(engineName = "ModelManager", errorMessage = t.message),                    )                    Pair(null, -1L)                }            }            // Wait for both.            val cameraMs = cameraDeferred.await()            val (omniSlmRuntime, modelMs) = modelDeferred.await()            // Determine which stack to use for first frame.            val cameraOk = cameraMs >= 0            val omniSlmReady = omniSlmRuntime != null && !omniSlmRuntime.isDisabled && omniSlmRuntime.isReady()            val isColdStart = modelMs > 500  // Cold start if model took > 500ms            if (isColdStart) totalColdStarts++ else totalWarmStarts++            val result = when {                !cameraOk -> {                    // Camera failed — can't do vision.                    _loadingState.value = FirstFrameLoadingState.FAILED                    FirstFrameResult(                        success = false,                        errorMessage = "Camera initialization failed",                        omniSlmRuntime = omniSlmRuntime,                        v2StackActive = false,                        usedOmniSlm = false,                        cameraOpenMs = cameraMs,                        modelLoadMs = modelMs,                        isColdStart = isColdStart,                    )                }                omniSlmReady -> {                    // Both camera + Omni-SLM ready — use Omni-SLM.                    usedOmniSlmForFirstFrame = true                    _loadingState.value = FirstFrameLoadingState.READY_OMNI_SLM                    Timber.tag(TAG).i("First-frame ready: Omni-SLM (camera=${cameraMs}ms, model=${modelMs}ms).")                    FirstFrameResult(                        success = true,                        errorMessage = null,                        omniSlmRuntime = omniSlmRuntime,                        v2StackActive = false,                        usedOmniSlm = true,                        cameraOpenMs = cameraMs,                        modelLoadMs = modelMs,                        isColdStart = isColdStart,                    )                }                else -> {                    // Camera ready but Omni-SLM not ready — use v2 stack fallback.                    usedOmniSlmForFirstFrame = false                    totalV2Fallbacks++                    _loadingState.value = FirstFrameLoadingState.READY_V2_FALLBACK                    Timber.tag(TAG).i("First-frame ready: v2 stack fallback (Omni-SLM loading in background).")                    FirstFrameResult(                        success = true,                        errorMessage = null,                        omniSlmRuntime = omniSlmRuntime,  // May become ready later                        v2StackActive = true,                        usedOmniSlm = false,                        cameraOpenMs = cameraMs,                        modelLoadMs = modelMs,                        isColdStart = isColdStart,                    )                }            }            result        }    }    /**     * Process the first camera frame using whatever model is ready.     *     * If Omni-SLM is ready → use it.     * If Omni-SLM is NOT ready → use v2 stack + schedule Omni-SLM upgrade.     *     * @param frame the first camera frame.     * @param onResult callback when the first result is ready.     * @param onUpgrade callback when Omni-SLM upgrades the result (if v2 was used first).     */    suspend fun processFirstFrame(        frame: RgbImage,        onResult: suspend (FirstFrameProcessResult) -> Unit,        onUpgrade: (suspend (FirstFrameProcessResult) -> Unit)? = null,    ) = withContext(dispatcher) {        _loadingState.value = FirstFrameLoadingState.PROCESSING_FIRST_FRAME        val processStart = System.currentTimeMillis()        // Check if Omni-SLM is now ready (it may have finished loading during camera open).        val omniSlmRuntime = modelManager.getOmniSlmRuntime()        val omniSlmReady = !omniSlmRuntime.isDisabled && omniSlmRuntime.isReady()        if (omniSlmReady) {            // Use Omni-SLM directly.            val result = processWithOmniSlm(omniSlmRuntime, frame)            val elapsedMs = System.currentTimeMillis() - processStart            Timber.tag(TAG).i("First frame processed with Omni-SLM (${elapsedMs}ms).")            _loadingState.value = FirstFrameLoadingState.DONE            onResult(result)        } else {            // Use v2 stack for instant result.            val v2Result = processWithV2Stack(frame)            val v2ElapsedMs = System.currentTimeMillis() - processStart            Timber.tag(TAG).i("First frame processed with v2 stack (${v2ElapsedMs}ms).")            _loadingState.value = FirstFrameLoadingState.DONE_V2_FALLBACK            onResult(v2Result)            // Schedule Omni-SLM upgrade in background.            if (onUpgrade != null) {                _loadingState.value = FirstFrameLoadingState.UPGRADING_TO_OMNI_SLM                try {                    // Wait for Omni-SLM to become ready (with timeout).                    var attempts = 0                    while (!omniSlmRuntime.isReady() && attempts < 20) {                        yield()                        kotlinx.coroutines.delay(100)  // Poll every 100ms                        attempts++                    }                    if (omniSlmRuntime.isReady()) {                        val upgradedResult = processWithOmniSlm(omniSlmRuntime, frame)                        val upgradeElapsedMs = System.currentTimeMillis() - processStart                        Timber.tag(TAG).i("Omni-SLM upgrade complete (${upgradeElapsedMs}ms total).")                        _loadingState.value = FirstFrameLoadingState.DONE_UPGRADED                        onUpgrade(upgradedResult)                    } else {                        Timber.tag(TAG).w("Omni-SLM not ready after 2s — keeping v2 result.")                        _loadingState.value = FirstFrameLoadingState.DONE                    }                } catch (t: Throwable) {                    Timber.tag(TAG).e("Omni-SLM upgrade failed — keeping v2 result.", t)                    _loadingState.value = FirstFrameLoadingState.DONE                }            }        }    }    /** Process a frame with Omni-SLM. */    private suspend fun processWithOmniSlm(        runtime: OmniSlmRuntime,        frame: RgbImage,    ): FirstFrameProcessResult {        val caption = runtime.captionImage(frame.pixels)        return FirstFrameProcessResult(            caption = caption.value ?: "I can see something but can't describe it.",            confidence = caption.confidence,            source = FrameProcessSource.OMNI_SLM,            processingTimeMs = 0,  // Set by caller        )    }    /** Process a frame with v2 stack (MiniLM + BERT-tiny + MobileViT). */    private suspend fun processWithV2Stack(frame: RgbImage): FirstFrameProcessResult {        val caption = v2StackProvider.captionWithV2(frame)        return FirstFrameProcessResult(            caption = caption ?: "Unable to caption this frame.",            confidence = 0.65f,  // v2 stack is lower confidence            source = FrameProcessSource.V2_STACK,            processingTimeMs = 0,  // Set by caller        )    }    /** Reset the loader (for next session). */    fun reset() {        _loadingState.value = FirstFrameLoadingState.IDLE        usedOmniSlmForFirstFrame = false    }    /** Get stats (for Settings → Debug). */    fun stats(): FirstFrameStats = FirstFrameStats(        totalColdStarts = totalColdStarts,        totalWarmStarts = totalWarmStarts,        totalV2Fallbacks = totalV2Fallbacks,        v2FallbackRate = if (totalColdStarts + totalWarmStarts > 0) {            totalV2Fallbacks.toFloat() / (totalColdStarts + totalWarmStarts)        } else 0f,    )    private companion object {        private const val TAG = "FirstFrameLoader"    }}// ──────────────────────────────────────────────────────────────────────────/** First-frame loading states. */enum class FirstFrameLoadingState(val displayName: String) {    IDLE("Idle"),    INITIALIZING("Initializing (parallel camera + model)"),    PROCESSING_FIRST_FRAME("Processing First Frame"),    READY_OMNI_SLM("Ready — Omni-SLM Active"),    READY_V2_FALLBACK("Ready — v2 Stack Fallback"),    UPGRADING_TO_OMNI_SLM("Upgrading to Omni-SLM"),    DONE("Done — Omni-SLM"),    DONE_V2_FALLBACK("Done — v2 Stack"),    DONE_UPGRADED("Done — Upgraded to Omni-SLM"),    FAILED("Failed"),}/** Result of [FirstFrameParallelLoader.initializeParallel]. */data class FirstFrameResult(    val success: Boolean,    val errorMessage: String?,    val omniSlmRuntime: OmniSlmRuntime?,    val v2StackActive: Boolean,    val usedOmniSlm: Boolean,    val cameraOpenMs: Long,    val modelLoadMs: Long,    val isColdStart: Boolean,) {    /** True if v2 stack is being used (Omni-SLM not ready). */    val needsUpgrade: Boolean get() = success && v2StackActive}/** Result of processing a frame. */data class FirstFrameProcessResult(    val caption: String,    val confidence: Float,    val source: FrameProcessSource,    val processingTimeMs: Long,)/** Which stack processed the frame. */enum class FrameProcessSource(val displayName: String) {    OMNI_SLM("Omni-SLM (unified VLA)"),    V2_STACK("v2 Stack (MiniLM + BERT-tiny + MobileViT)"),}/** Stats for Settings → Debug. */data class FirstFrameStats(    val totalColdStarts: Int,    val totalWarmStarts: Int,    val totalV2Fallbacks: Int,    val v2FallbackRate: Float,) {    /** Total starts (cold + warm). */    val totalStarts: Int get() = totalColdStarts + totalWarmStarts    /** Cold start rate (%). */    val coldStartRate: Float        get() = if (totalStarts > 0) totalColdStarts.toFloat() / totalStarts else 0f}// ──────────────────────────────────────────────────────────────────────────/** * Camera provider interface — abstracts Camera2 API for testability. * * Production: [Camera2Provider] wraps Camera2 API (open camera + start preview + capture frame). * Tests: [FakeCameraProvider] returns canned camera open time + frames. */interface CameraProvider {    /** Open the camera (returns when camera is ready for preview). */    suspend fun openCamera()    /** Capture a single frame. */    suspend fun captureFrame(): RgbImage?    /** Close the camera. */    suspend fun closeCamera()    /** True if camera is currently open. */    fun isOpen(): Boolean}/** * V2 Stack provider interface — abstracts the vision-to-text pipeline. * * Production: Real implementation wraps the OmniSLM + OCR pipeline. */interface V2StackProvider {    suspend fun captionWithV2(frame: RgbImage): String?}
